s = input().strip()
if len(s) != 8 or not all(c in ("0", "1") for c in s):
    print("INVALID_BINARY")
else:
    terms = []
    for i, bit in enumerate(s):
        if bit == "1":
            terms.append(2 ** (7 - i))
    if not terms:
        print("0 = 0")
    else:
        expr = " + ".join(str(t) for t in terms)
        print(f"{expr} = {sum(terms)}")

n, width = [int(x) for x in input().split()]
if n < 0 or width < 1 or n >= (1 << width):
    print("OVERFLOW")
else:
    bits = []
    for _ in range(width):
        bits.append(str(n % 2))
        n //= 2
    bits.reverse()
    print("".join(bits))

s = input().strip()
if s.startswith("0b"):
    s = s[2:]
if not s or not all(c in ("0", "1") for c in s):
    print("INVALID_BINARY")
else:
    acc = 0
    for ch in s:
        acc = acc * 2 + (1 if ch == "1" else 0)
    print(acc)

nums = [int(x) for x in input().split()]
evens = []
odds = []
for x in nums:
    if (x & 1) == 0:
        evens.append(str(x))
    else:
        odds.append(str(x))
print("Evens: " + (" ".join(evens) if evens else "NONE"))
print("Odds: " + (" ".join(odds) if odds else "NONE"))

reg = int(input()) & 0xFF
q = int(input())
for _ in range(q):
    op, k_s = input().split()
    k = int(k_s)
    mask = 1 << k
    if op == "SET":
        reg |= mask
    elif op == "CLEAR":
        reg &= (~mask) & 0xFF
    elif op == "TOGGLE":
        reg ^= mask
    elif op == "CHECK":
        print((reg >> k) & 1)
print(f"Register: {reg} ({reg:08b})")

FLAGS = {"R": 4, "W": 2, "X": 1}
perm = int(input()) & 7
q = int(input())
for _ in range(q):
    op, key = input().split()
    flag = FLAGS[key]
    if op == "GRANT":
        perm |= flag
    elif op == "REVOKE":
        perm &= (~flag) & 7
    elif op == "CAN":
        print("ALLOW" if (perm & flag) else "DENY")

rwx = "".join(ch if (perm & bit) else "-" for bit, ch in ((4, "r"), (2, "w"), (1, "x")))
print(f"Final: {perm} ({rwx})")
